// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        // admin is the deployer (this test contract); exclude it so the caller is genuinely unauthorized
        vm.assume(actor != address(this));
        // exclude a no-op rename so any success necessarily mutates owner
        vm.assume(newOwner != c.owner());
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.owner() == address(this));
    }
}
